package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.New(0, 0)
var WsTotal decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanFile *os.File
var loanScanner *bufio.Scanner
var inputDone bool

func formatEdited(val decimal.Decimal, pic string) string {
	// Determine sign - these fields are positive in this program
	neg := val.Sign() < 0
	if neg {
		val = val.Neg()
	}
	// Split picture into integer and fractional parts
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	// Count digit slots
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}
	// Extract integer and fractional strings of val
	// val is already scaled to appropriate size; we need truncated representation
	// For edited move, truncate toward zero to fracSlots
	if fracSlots > 0 {
		val = val.Truncate(int32(fracSlots))
	} else {
		val = val.Truncate(0)
	}
	// Get integer part and fractional part as strings
	// Use string representation with exactly fracSlots digits
	var intStr string
	var fracStr string
	if fracSlots > 0 {
		s := val.StringFixed(int32(fracSlots)) // e.g. "1000.00"
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		fracStr = parts[1]
	} else {
		s := val.StringFixed(0)
		if strings.HasPrefix(s, "-") {
			s = s[1:]
		}
		intStr = s
		fracStr = ""
	}
	// Handle high-order digit truncation: keep only low-order intSlots digits
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// Pad integer with leading zeros to intSlots
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}

	// Build integer edited field
	var intResult []rune
	digitIdx := 0
	suppressed := true
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if suppressed {
				if d != '0' {
					suppressed = false
					intResult = append(intResult, rune(d))
				} else {
					if ch == 'Z' {
						intResult = append(intResult, ' ')
					} else {
						// 9 in leading zero area: prints 0 and ends suppression
						suppressed = false
						intResult = append(intResult, '0')
					}
				}
			} else {
				intResult = append(intResult, rune(d))
			}
		} else if ch == ',' {
			if suppressed {
				intResult = append(intResult, ' ')
			} else {
				intResult = append(intResult, ',')
			}
		} else {
			intResult = append(intResult, ch)
		}
	}
	// If all integer digits were zero and suppressed (e.g., value 0 with ZZZ...9),
	// the logic above already produced "   ...0"
	// Build fractional part
	var fracResult []rune
	if dotIdx >= 0 {
		intResult = append(intResult, '.')
		// fracPic consists of Z/9 ; for this program all 9
		for i, ch := range fracPic {
			if ch == 'Z' || ch == '9' {
				if i < len(fracStr) {
					fracResult = append(fracResult, rune(fracStr[i]))
				} else {
					fracResult = append(fracResult, '0')
				}
			} else {
				fracResult = append(fracResult, ch)
			}
		}
		intResult = append(intResult, fracResult...)
	}
	res := string(intResult)
	// Ensure length equals pic length (should)
	if len(res) != len(pic) {
		// Pad/truncate if needed
		if len(res) < len(pic) {
			res = strings.Repeat(" ", len(pic)-len(res)) + res
		}
	}
	if neg {
		// Put minus sign into last leading space if possible (not needed for this data)
		b := []byte(res)
		for i := len(b) - 1; i >= 0; i-- {
			if b[i] == ' ' {
				b[i] = '-'
				break
			}
		}
		res = string(b)
	}
	return res
}

func storeTruncate(val decimal.Decimal, scale int32, intDigits int) decimal.Decimal {
	v := val.Truncate(scale)
	// Simulate high-order digit dropping for PIC 9(n)V99 etc.
	// Keep only low-order digits that fit. For this program overflow doesn't occur
	// except potentially, but implement general: total digits = intDigits + scale
	// Drop high-order by modulo 10^(intDigits+scale) then re-scale?
	// Use decimal modulo.
	mod := decimal.New(1, int32(intDigits+int(scale))).Add(decimal.New(0, 0)) // 10^(n)
	// Actually 10^(intDigits+scale)
	// For positive values: v mod 10^n scaled
	// For simplicity if v >= 10^(intDigits) with scale, truncate high order
	limit := decimal.New(1, int32(intDigits)).Mul(decimal.New(1, 0)) // 10^intDigits
	// v integer part limit check
	if intDigits > 0 {
		// Use absolute
		av := v
		if av.Sign() < 0 {
			av = av.Neg()
		}
		// compare av >= 10^intDigits
		pow10 := decimal.New(1, int32(intDigits)) // 10^intDigits
		if av.Cmp(pow10) >= 0 {
			// Keep fractional part and low-order integer digits
			// Compute v mod pow10 with scale preservation
			// v = intPart + frac ; low = (intPart mod pow10) + frac
			// Use Shift to get integer representation
			shifted := v.Shift(int32(scale)) // integer
			m := decimal.New(1, int32(intDigits+int(scale)))
			// modulo for positive; for negative need COBOL semantics (keep low digits of magnitude)
			sign := v.Sign()
			if sign < 0 {
				shifted = shifted.Neg()
			}
			rem := shifted.Mod(m)
			if sign < 0 {
				rem = rem.Neg()
			}
			v = rem.Shift(-int32(scale))
		}
	}
	_ = mod
	_ = limit
	return v
}

func main() {
	var err error
	loanFile, err = os.Open("input.dat")
	if err != nil {
		// If file doesn't exist, treat as empty
		if os.IsNotExist(err) {
			loanFile = nil
			loanScanner = bufio.NewScanner(strings.NewReader(""))
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	if loanFile != nil {
		loanScanner = bufio.NewScanner(loanFile)
	}
	WsEofFlag = "N"
	inputDone = false
	// Prepare LoanRec zero
	MAIN_PARA()
	if loanFile != nil {
		loanFile.Close()
	}
}

func MAIN_PARA() {
	// OPEN INPUT LOAN-FILE already done
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE handled in main after loop, but do here
	if loanFile != nil {
		loanFile.Close()
		loanFile = nil
	}
	SUMMARY_PARA()
}

var curLoan LoanRec
var hasRecord bool

func READ_PARA() {
	if loanScanner == nil || !loanScanner.Scan() {
		WsEofFlag = "Y"
		inputDone = true
		hasRecord = false
		return
	}
	line := loanScanner.Text()
	// Pad with spaces to 21
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	// Parse fields
	acct := line[0:6]
	prinStr := line[6:15]
	rateStr := line[15:19]
	yearsStr := line[19:21]

	// Parse numeric fields: digits only, implied decimal
	prinStr = strings.TrimSpace(prinStr)
	if prinStr == "" {
		prinStr = "0"
	}
	prinInt, _ := decimal.NewFromString(prinStr)
	// prinStr may have leading zeros; decimal.NewFromString works
	prinVal := decimal.New(prinInt.IntPart(), -2)

	rateStr = strings.TrimSpace(rateStr)
	if rateStr == "" {
		rateStr = "0"
	}
	rateInt, _ := decimal.NewFromString(rateStr)
	rateVal := decimal.New(rateInt.IntPart(), -2)

	yearsStr = strings.TrimSpace(yearsStr)
	var years int64
	if yearsStr != "" {
		fmt.Sscanf(yearsStr, "%d", &years)
	}

	curLoan = LoanRec{
		LrAcct:      acct,
		LrPrincipal: prinVal,
		LrRate:      rateVal,
		LrYears:     years,
	}
	hasRecord = true
	WsEofFlag = "N"
	inputDone = false
}

func PROCESS_PARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	// Use decimal arithmetic multiply before divide
	tmp := curLoan.LrPrincipal.Mul(curLoan.LrRate).Mul(decimal.New(curLoan.LrYears, 0))
	tmp = tmp.Shift(-2) // divide by 100
	// Rounded to scale 2
	WsInterest = tmp.Round(2)
	// store truncate to PIC 9(9)V99 scale2 intDigits 9
	WsInterest = storeTruncate(WsInterest, 2, 9)

	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = storeTruncate(WsTotal, 2, 11)

	WsCount = WsCount + 1
	// overflow for 9(5) would modulo 100000; not needed

	WsPrinEd = formatEdited(curLoan.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s\n", curLoan.LrAcct, WsPrinEd, WsIntEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	// WS-COUNT is PIC 9(5) zero-padded to 5
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}
